def main():
    v=json.loads(VOCAB_PATH.read_text(encoding='utf-8')); p=json.loads(PHRASE_PATH.read_text(encoding='utf-8')); t=p.setdefault('translations',{}); rows=[x for x in v if int(x.get('level',0))==4][:100]; expected={str(x['word']).casefold() for x in rows}; assert expected <= set(EN) and expected <= set(JA)
    for x in rows:
        w=str(x['word']).casefold(); x['example']=EN[w]; ex=t.setdefault(f"builtin:{x['id']}",{}).setdefault('example',{}); ex.update(source=EN[w],en=EN[w],ja=JA[w])
    VOCAB_PATH.write_text(json.dumps(v,ensure_ascii=False,indent=1)+'\n',encoding='utf-8'); PHRASE_PATH.write_text(json.dumps(p,ensure_ascii=False,indent=1)+'\n',encoding='utf-8'); print(f'reviewed 800+ English/Japanese examples batch 1: {len(rows)} terms')
if __name__=='__main__': main()
